int remaining(int N,int *T,int *V){
    int water=0;
    for(int i=0;i<N;i++){
        if(i==0) water = 0;
        else {
            int dt = T[i]-T[i-1];
            water -= dt;
            if(water<0) water=0;
        }
        water += V[i];
    }
    return water;
}

